---SetNodeInfo
---设置 BuffNodeInfo
function UIBattlingBuffListNode:SetNodeInfo(buffData)
    local lbBuffNode = self.UIBattlingCharactorBuffIcon
    local buffNode
    if lbBuffNode then
        lbBuffNode:Init()
        buffNode = lbBuffNode.Env
    end
    local buffVo = UIBattlingTools.GetBuffDataPath(buffData.showId)
    if isNull(buffVo) then return end
    --- 获取 buffIcon 资源路径
    local buffIconPath = IsNull(buffVo) and "" or buffVo.icon
    --- BuffNode
    if buffNode then
        if not string.isEmpty(buffIconPath) then
            buffNode:SetBuffIconIMG(buffIconPath)
            buffNode:SetShowNodeActiveState(true)
            buffNode:InitBuffNode(buffData.buffId, buffData.round, buffIconPath)
            buffNode:SetNodeTxt(buffData.buffRemainNum, buffData.buffLayer) -- 设置 BuffNode 的 TXT
            KTool.SetActive(self.UIBattlingCharactorBuffIcon.gameObject, not string.isEmpty(buffIconPath))
        end
        --buffNode:SetNodeTxt(buffData.buffRemainNum, buffData.buffLayer)
    end
    --- 设置人物 buff 描述
    -- print("[Buff]", buffData.buffId, buffData.effectStars, table.dump(buffData, nil, 5), debug.traceback())
    local showBuffName, showBuffDes = CardProgressionSkillUtils.ParseSkillBuffDesc(buffData.buffId, buffData.effectStars)
    self.NameText.text = checkString(showBuffName)
    self.DesText.text = buffVo.showRegisterValue == 0 and checkString(showBuffDes) or checkString(showBuffDes)..math.ceil(buffData.attacker:GetRegister1())
    -- print("->UIBattlingBuffListNode:SetNodeInfo:", table.dump(buffData))
    local isShowPassive = (isSet(buffData, "isPassive") and buffData.isPassive > 0)
    KTool.SetActive(self.PassiveText.gameObject, isShowPassive)
    KTool.SetActive(self.RT_ExtraInfoRoot, isShowPassive)

    local extraDescription = self:DescriptionSpecial(buffData)
    if extraDescription and extraDescription ~= "" then
        self.ExtraText.text = checkString(extraDescription)
        KTool.SetActive(self.RT_ExtraInfoRoot, true)
    end

    local showLayer = buffData.buffLayer >= 1
    local showRound = (1 <= buffData.buffRemainNum and buffData.buffRemainNum <= 99)
    if showLayer or showRound then
        KTool.SetActive(self.RT_LayerAndRoundRoot, true)

        local layer = showLayer and (localize("_num_层", {_num_ = checkInt(buffData.buffLayer)})) or ""
        local round = showRound and (localize("持续_num_回合", {_num_ = checkInt(buffData.buffRemainNum)})) or ""
        local split = (showLayer and showRound) and "," or ""

        self.Txt_LayerAndRound.text = layer .. split .. round
    end

    local buffType = buffData.type
    if buffType == 1 then
        self.SImg_ImgPress.Status = 1
        self.Txt_Type.text = localize("增益")
        self.STxt_Type.Status = 1
    elseif buffType == 2 then
        self.SImg_ImgPress.Status = 2
        self.Txt_Type.text = localize("减益")
        self.STxt_Type.Status = 2
    elseif buffType == 0 then
        self.SImg_ImgPress.Status = 3
        self.Txt_Type.text = localize("中立")
        self.STxt_Type.Status = 3
    end
end

---GetBuffLayer
---获取 Buff 层数信息
function UIBattlingBuffListNode:GetBuffLayer(buffData)
    local strResult = {}
    if not IsNull(buffData.buffLayer) and buffData.buffLayer > 1 then
        return string.format("%s", checkString(buffData.buffLayer))
    end
    return table.concat(strResult)
end

---DescriptionSpecial
---获取额外描述 (唯一，不可驱散)
---@param buffData table
function UIBattlingBuffListNode:DescriptionSpecial(buffData)
    local strResult = {}
    --- 检索可驱散字段
    if checkNumber(buffData.isClear) < 1 then
        table.insert(strResult,localize("不可驱散"))
    end
    --- 检索唯一字段
    if checkNumber(buffData.isUnique[1]) > 0 then
        table.insert(strResult,localize("唯一"))
    end
    local listSplit = {}
    if #strResult > 1 then
        for i = 1, #strResult - 1 do
            table.insert(listSplit, "&")
        end
    end
    local final = {}
    for i = 1, #strResult do
        if strResult[i] then
            table.insert(final, strResult[i])
        end
        if listSplit[i] then
            table.insert(final, listSplit[i])
        end
    end
    return #strResult > 0 and table.concat(final) or ""
end

return UIBattlingBuffListNode
